use strict;
use warnings;
use File::Temp qw(tempfile);

sub ascii85_decode {
    my ($s) = @_;
    $s =~ s/\s+//g;
    $s =~ s/~>$//;
    my $out = '';
    my @g;
    while (length $s) {
        my $c = substr($s,0,1,'');
        next if $c eq '';
        if ($c eq 'z') {
            die "bad ascii85" if @g;
            $out .= "\0\0\0\0";
            next;
        }
        die "bad ascii85 char" if ord($c) < 33 || ord($c) > 117;
        push @g, ord($c)-33;
        if (@g == 5) {
            my $n = 0;
            $n = $n * 85 + $_ for @g;
            $out .= pack('N',$n);
            @g = ();
        }
    }
    if (@g) {
        my $n = scalar @g;
        push @g, (84) x (5-$n);
        my $v = 0;
        $v = $v * 85 + $_ for @g;
        my $b = pack('N',$v);
        $out .= substr($b,0,$n-1);
    }
    return $out;
}

sub flate_decode {
    my ($z) = @_;
    die "not zlib" unless length($z) >= 6;
    my $raw = substr($z,2,length($z)-6);
    my ($fh,$fn) = tempfile('/tmp/pdfinflateXXXXXX', UNLINK=>0);
    binmode $fh;
    print $fh "\x1f\x8b\x08\x00\x00\x00\x00\x00\x00\x03", $raw, "\0" x 8;
    close $fh;
    my ($oh,$on) = tempfile('/tmp/pdfoutXXXXXX', UNLINK=>0);
    close $oh;
    my $rc = system('gzip','-dc',$fn);
    # Above writes stdout to terminal; decode again redirecting via shell-safe fixed temp names.
    unlink $on;
    system("gzip -dc '$fn' > '$on' 2>/dev/null");
    open my $in, '<:raw', $on or die $!;
    local $/;
    my $out = <$in>;
    close $in;
    unlink $fn, $on;
    return $out;
}

for my $fn (@ARGV) {
    open my $fh, '<:raw', $fn or die "$fn: $!";
    local $/;
    my $pdf = <$fh>;
    close $fh;
    print "===== $fn =====\n";
    while ($pdf =~ /stream\r?\n(.*?)\r?\nendstream/sg) {
        my $raw = $1;
        my $before = substr($pdf, $-[0] > 400 ? $-[0]-400 : 0, 400);
        my $is_a85 = $before =~ /ASCII85Decode/;
        my $is_flate = $before =~ /FlateDecode/;
        my $data = $raw;
        $data = ascii85_decode($data) if $is_a85;
        $data = flate_decode($data) if $is_flate;
        print "-- stream raw=" . length($raw) . " decoded=" . length($data) . " a85=$is_a85 flate=$is_flate --\n";
        my $display = $data;
        $display =~ s/[^\x09\x0a\x0d\x20-\x7e]/./g;
        print $display, "\n";
    }
}

